def collect(c):
 require(sha(PREVIOUS)==PREVIOUS_SHA,'Previous database changed');require(c.execute('SELECT count(*)FROM remaining_usable_keys').fetchone()[0]==41242,'Previous admissions changed');q=c.execute('SELECT * FROM remaining_numeric_queue ORDER BY book,row_number');names=[n[0]for n in q.description];data=[dict(zip(names,v))for v in q.fetchall()];require(len(data)==5971,'Previous queue changed');r=FinalResolver();rows=[];reviews=[]
