def expressions():return [('final_family_usable_keys','SELECT * FROM remaining_usable_keys UNION ALL SELECT book,row_number FROM final_family_observations'),('final_family_numeric_queue',"SELECT s.*,s.remaining_reason final_family_reason FROM remaining_numeric_queue s LEFT JOIN final_family_review r USING(book,row_number)WHERE COALESCE(r.status,'')<>'usable_final_family'")]
def build(output):
 output=Path(output).resolve();require(output.is_relative_to(ROOT)and not output.exists(),'Output must be new project directory');require(sha(PREVIOUS)==PREVIOUS_SHA,'Previous database changed');output.mkdir(parents=True);db=output/'final_families.duckdb';shutil.copyfile(PREVIOUS,db)
