  require(not c.execute("SELECT table_name FROM information_schema.tables WHERE table_name LIKE 'final_family_%'").fetchall(),'Final family namespace collision');rows,reviews,pages,diag=collect(c);c.execute('CREATE TABLE final_family_observations AS SELECT * FROM remaining_observations WHERE false');c.execute('ALTER TABLE final_family_observations ADD PRIMARY KEY(book,row_number)')
